use vstd::prelude::*;

verus! {

fn reverse(s: Vec<i8>) -> (rev: Vec<i8>)
    ensures
        rev.len() == s.len(),
        forall|k: int| 0 <= k < s.len() ==> rev[k] == s[s.len() - 1 - k],
{
    let mut rev: Vec<i8> = Vec::new();
    let mut i: usize = s.len();
    
    while i > 0
        invariant
            i <= s.len(),
            rev.len() == s.len() - i,
            forall|k: int| 0 <= k < rev.len() ==> rev[k] == s[s.len() - 1 - k],
        decreases i,
    {
        i = i - 1;
        rev.push(s[i]);
    }
    
    rev
}

}
